import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_reciprocal_TriageGen2Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testReciprocal_RealDominant() {
        // Case where |real| >= |imaginary|
        // q = imaginary / real
        // scale = 1 / (imaginary * q + real)
        // return (scale, -scale * q)
        Complex c = new Complex(2.0, 1.0);
        Complex result = c.reciprocal();

        // q = 0.5
        // scale = 1 / (1.0 * 0.5 + 2.0) = 1 / 2.5 = 0.4
        // real = 0.4, imag = -0.4 * 0.5 = -0.2
        assertEquals(0.4, result.getReal(), EPSILON);
        assertEquals(-0.2, result.getImaginary(), EPSILON);
    }






}

