public class Complex_reciprocal_TriageGen2Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testReciprocal_ImaginaryDominant() {
        // Case where |real| < |imaginary|
        // q = real / imaginary
        // scale = 1 / (real * q + imaginary)
        // return (scale * q, -scale)
        Complex c = new Complex(1.0, 2.0);
        Complex result = c.reciprocal();

        // q = 0.5
        // scale = 1 / (1.0 * 0.5 + 2.0) = 0.4
        // real = 0.4 * 0.5 = 0.2, imag = -0.4
        assertEquals(0.2, result.getReal(), EPSILON);
        assertEquals(-0.4, result.getImaginary(), EPSILON);
    }




}

